cat > main.ts <<'EOF'
const text = await Deno.readTextFile(Deno.args[0]);
const tokens = text.split(/\s+/).filter((t) => t.length > 0).map(Number);
const [width, height, steps] = tokens;
const cells = width * height;
const input = new Uint32Array(cells);
for (let i = 0; i < cells; i++) input[i] = tokens[3 + i] ?? 0;

const adapter = await navigator.gpu.requestAdapter();
if (!adapter) throw new Error("no WebGPU adapter available");
const device = await adapter.requestDevice();

const shader = device.createShaderModule({
  code: `
struct Dims { w: u32, h: u32 };
@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;
@group(0) @binding(2) var<uniform> dims: Dims;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
  if (id.x >= dims.w || id.y >= dims.h) { return; }
  let x = id.x;
  let y = id.y;
  let l = select(x - 1u, x, x == 0u);
  let r = select(x + 1u, x, x + 1u >= dims.w);
  let u = select(y - 1u, y, y == 0u);
  let d = select(y + 1u, y, y + 1u >= dims.h);
  let s = 4u * src[y * dims.w + x] + src[y * dims.w + l] + src[y * dims.w + r]
        + src[u * dims.w + x] + src[d * dims.w + x];
  dst[y * dims.w + x] = s / 8u;
}`,
});

const pipeline = device.createComputePipeline({
  layout: "auto",
  compute: { module: shader, entryPoint: "main" },
});

const size = Math.max(cells * 4, 4);
const usage = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST;
const bufs = [device.createBuffer({ size, usage }), device.createBuffer({ size, usage })];
device.queue.writeBuffer(bufs[0], 0, input);
const dimsBuf = device.createBuffer({
  size: 16,
  usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
});
device.queue.writeBuffer(dimsBuf, 0, new Uint32Array([width, height, 0, 0]));

const groups = [0, 1].map((i) =>
  device.createBindGroup({
    layout: pipeline.getBindGroupLayout(0),
    entries: [
      { binding: 0, resource: { buffer: bufs[i] } },
      { binding: 1, resource: { buffer: bufs[1 - i] } },
      { binding: 2, resource: { buffer: dimsBuf } },
    ],
  })
);

const readback = device.createBuffer({
  size,
  usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
});
const encoder = device.createCommandEncoder();
for (let s = 0; s < steps; s++) {
  const pass = encoder.beginComputePass();
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, groups[s % 2]);
  pass.dispatchWorkgroups(Math.ceil(width / 16), Math.ceil(height / 16));
  pass.end();
}
encoder.copyBufferToBuffer(bufs[steps % 2], 0, readback, 0, size);
device.queue.submit([encoder.finish()]);
await readback.mapAsync(GPUMapMode.READ);
const out = new Uint32Array(readback.getMappedRange().slice(0));
readback.unmap();

const lines: string[] = [];
let sum = 0;
for (let y = 0; y < height; y++) {
  const row: number[] = [];
  for (let x = 0; x < width; x++) {
    const v = out[y * width + x];
    sum += v;
    row.push(v);
  }
  lines.push(row.join(" "));
}
lines.push(`SUM ${sum}`);
console.log(lines.join("\n"));
device.destroy();
EOF
